let cache: { js: Uint8Array; wasm: Uint8Array } | null = null;

/** The pinned bytes for an allow-listed name. Decoded once per server instance; callers get a fresh copy. */
export function binjgbVendorBytes(name: 'binjgb.js' | 'binjgb.wasm'): Uint8Array {
  if (!cache) cache = { js: new Uint8Array(Buffer.from(JS_BASE64, 'base64')), wasm: new Uint8Array(Buffer.from(WASM_BASE64, 'base64')) };
  return (name === 'binjgb.js' ? cache.js : cache.wasm).slice();
}
